package com.smartlibrary.service;
import com.smartlibrary.model.*;import com.smartlibrary.repository.*;import java.util.*;import java.time.*;import java.nio.file.*;
public class LibraryService { private final LibraryRepository repo;private final Map<String,Book> books;private final List<BorrowRecord> records;private final List<Reservation> reservations;private final Map<String,User> users=new LinkedHashMap<>();
 public LibraryService(LibraryRepository repo){this.repo=repo;books=repo.loadBooks();records=repo.loadRecords();reservations=repo.loadReservations();users.put("U001",new User("U001","Demo Student"));if(books.isEmpty()){seed();save();}}
 private void seed(){addBook(new Book("B001","Algorithms Unlocked","Thomas Cormen","9780262518802","Algorithms","An accessible introduction to algorithms, problem solving, graphs and data structures.",3,3,240,9));addBook(new Book("B002","Clean Code","Robert C. Martin","9780132350884","Programming","Practical software craftsmanship and readable code design.",2,2,360,8));addBook(new Book("B003","Introduction to Machine Learning","Ethem Alpaydin","9780262028189","AI","Statistical learning, classification, model selection and data analysis.",2,2,420,10));addBook(new Book("B004","Operating System Concepts","Silberschatz","9781119800361","Systems","Processes, scheduling, memory, concurrency and system calls.",1,1,480,8));}
 public Collection<Book> allBooks(){return Collections.unmodifiableCollection(books.values());} public Optional<Book> find(String id){return Optional.ofNullable(books.get(id));}public Collection<User> users(){return users.values();}public List<BorrowRecord> records(){return Collections.unmodifiableList(records);}public List<Reservation> reservations(){return Collections.unmodifiableList(reservations);}
 public void addBook(Book b){if(books.containsKey(b.getId()))throw new IllegalArgumentException("Book ID already exists");books.put(b.getId(),b);}
 public void deleteBook(String id){Book b=books.get(id);if(b==null)throw new IllegalArgumentException("Unknown book ID");if(b.getAvailableCopies()!=b.getTotalCopies())throw new IllegalStateException("Cannot delete a borrowed book");books.remove(id);}
 public void borrow(String userId,String bookId){Book b=require(bookId);if(!users.containsKey(userId))throw new IllegalArgumentException("Unknown user. Demo user is U001.");b.borrow();records.add(new BorrowRecord(userId,bookId,LocalDate.now(),null));save();}
 public void giveBack(String userId,String bookId){Book b=require(bookId);for(int i=records.size()-1;i>=0;i--){BorrowRecord r=records.get(i);if(r.userId().equals(userId)&&r.bookId().equals(bookId)&&r.returnedOn()==null){records.set(i,r.returned());b.giveBack();fulfillReservation(bookId);save();return;}}throw new IllegalArgumentException("No active borrowing record found for this user/book");}
 public void reserve(String userId,String bookId){require(bookId);if(!users.containsKey(userId))throw new IllegalArgumentException("Unknown user. Demo user is U001.");if(reservations.stream().anyMatch(r->r.userId().equals(userId)&&r.bookId().equals(bookId)&&!r.fulfilled()))throw new IllegalStateException("Active reservation already exists");reservations.add(new Reservation(userId,bookId,LocalDateTime.now(),false));save();}
 private void fulfillReservation(String id){for(int i=0;i<reservations.size();i++){Reservation r=reservations.get(i);if(r.bookId().equals(id)&&!r.fulfilled()){reservations.set(i,new Reservation(r.userId(),r.bookId(),r.createdAt(),true));break;}}}
 public List<Book> search(String q){String x=q.toLowerCase(Locale.ROOT);return books.values().stream().filter(b->(b.getTitle()+" "+b.getAuthor()+" "+b.getIsbn()+" "+b.getCategory()+" "+b.getDescription()).toLowerCase(Locale.ROOT).contains(x)).toList();}
 public List<Book> popular(){Map<String,Long> counts=new HashMap<>();records.forEach(r->counts.merge(r.bookId(),1L,Long::sum));return books.values().stream().sorted(Comparator.comparingLong((Book b)->counts.getOrDefault(b.getId(),0L)).reversed()).toList();}
 public void save(){repo.saveBooks(books.values());repo.saveRecords(records);repo.saveReservations(reservations);}private Book require(String id){Book b=books.get(id);if(b==null)throw new IllegalArgumentException("Unknown book ID");return b;}
}
